class FakeModule(object):
    def __init__(self):
        self.commands = []
        self.warnings = []

    def get_bin_path(self, command):
        assert command == 'sysctl'
        return '/sbin/sysctl'

    def run_command(self, command):
        self.commands.append(command)
        return 0, (
            'kernel.ostype = Linux\n'
            'kern.bootfile: /boot/kernel/kernel\n'
            'example.multiline = first line\n'
            ' second line\n'
            ' third line\n'
            '\n'
        ), ''

    def warn(self, message):
        self.warnings.append(message)

module = FakeModule()

result = get_sysctl(module, ['kernel.ostype', 'kern.bootfile'])

assert module.commands == [[
    '/sbin/sysctl',
    'kernel.ostype',
    'kern.bootfile',
]]
assert module.warnings == []
assert result == {
    'kernel.ostype': 'Linux',
    'kern.bootfile': '/boot/kernel/kernel',
    'example.multiline': 'first line\n second line\n third line',
}

